insert into public.place_translations(place_id,organization_id,locale,name,short_description) values('a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','en','The Willow Museum','FICTIONAL DEMO');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000010','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','en','The main entrance','A wide, step-free path leads to the glass doors. There is a bench beside the entrance. The doors open automatically.','Street sounds may be noticeable. You can pause on the bench before entering.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000011','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','en','Reception & the foyer','The reception desk is on your left. A staff member can explain the route. Toilets are along the corridor to the right.','Groups may gather here. Ask about a shorter route or a quieter place to wait.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000012','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','en','The collection gallery','Paintings hang on pale walls. There are benches in the centre. This example room has no background music.','Light is steady. You can walk around the room in either direction.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000013','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','en','The interactive gallery','Screens and hands-on displays fill this room. Some exhibits produce short sounds. Screen brightness can change.','You can skip this room. Staff can show you the route to the quiet room.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000014','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','en','The quiet room','This small room has softer light, chairs and a window overlooking a garden. In this example, it is available throughout the visit.','Use the space for a pause. Ask staff if it is occupied. The room is not soundproof.');
insert into public.place_translations(place_id,organization_id,locale,name,short_description) values('a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','ro','Muzeul Willow','FICTIONAL DEMO');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000010','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','ro','Intrarea principală','Un traseu larg, fără trepte, duce la ușile de sticlă. Lângă intrare se află o bancă. Ușile se deschid automat.','Se pot auzi sunete de pe stradă. Poți lua o pauză pe bancă înainte de intrare.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000011','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','ro','Recepția și holul','Recepția este în stânga. Un membru al echipei poate explica traseul. Toaletele sunt pe coridorul din dreapta.','Aici se pot aduna grupuri. Poți cere un traseu mai scurt sau un loc mai liniștit pentru așteptare.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000012','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','ro','Galeria colecției','Tablourile sunt expuse pe pereți deschiși la culoare. În centru sunt bănci. În această sală exemplu nu există muzică de fundal.','Lumina este constantă. Poți parcurge sala în ambele direcții.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000013','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','ro','Galeria interactivă','În sală sunt ecrane și exponate interactive. Unele emit sunete scurte. Luminozitatea ecranelor se poate schimba.','Poți sări această sală. Personalul îți poate arăta traseul către camera liniștită.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000014','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','ro','Camera liniștită','Această cameră mică are lumină mai blândă, scaune și o fereastră spre grădină. În exemplu, este disponibilă pe parcursul vizitei.','Poți lua o pauză aici. Întreabă personalul dacă este ocupată. Camera nu este izolată fonic.');
insert into public.place_translations(place_id,organization_id,locale,name,short_description) values('a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','de','Das Willow Museum','FICTIONAL DEMO');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000010','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','de','Der Haupteingang','Ein breiter, stufenloser Weg führt zu den Glastüren. Neben dem Eingang steht eine Bank. Die Türen öffnen automatisch.','Straßengeräusche können hörbar sein. Auf der Bank können Sie vor dem Eintritt pausieren.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000011','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','de','Empfang & Foyer','Der Empfang liegt links. Das Personal kann den Weg erklären. Toiletten befinden sich im rechten Flur.','Hier können sich Gruppen sammeln. Fragen Sie nach einem kürzeren Weg oder einem ruhigeren Warteplatz.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000012','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','de','Die Sammlungsgalerie','Gemälde hängen an hellen Wänden. In der Mitte stehen Bänke. In diesem Beispielraum gibt es keine Hintergrundmusik.','Das Licht ist gleichmäßig. Sie können in beide Richtungen durch den Raum gehen.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000013','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','de','Die interaktive Galerie','Bildschirme und interaktive Stationen füllen den Raum. Einige erzeugen kurze Geräusche. Die Bildschirmhelligkeit kann wechseln.','Sie können diesen Raum überspringen. Das Personal zeigt den Weg zum Ruheraum.');
insert into public.zone_translations(zone_id,place_id,organization_id,locale,title,description,useful_note) values('a0000000-0000-4000-8000-000000000014','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001','de','Der Ruheraum','Dieser kleine Raum bietet weicheres Licht, Stühle und ein Gartenfenster. Im Beispiel ist er während des Besuchs verfügbar.','Nutzen Sie den Raum für eine Pause. Fragen Sie, ob er besetzt ist. Er ist nicht schalldicht.');
